class ThresholdStrategy { compute(values) { throw new Error('not implemented') } }
class StaticThreshold extends ThresholdStrategy {
  constructor(v){ super(); this.v=v }
  compute(_){ return this.v }
}
class PercentileThreshold extends ThresholdStrategy {
  constructor(p){ super(); this.p=p }
  compute(values){ if (!values.length) return 0; values.sort((a,b)=>a-b); const idx=Math.floor((this.p/100)*(values.length-1)); return values[idx]; }
}
class RollingWindowThreshold extends ThresholdStrategy {
  constructor(size){ super(); this.size=size }
  compute(values){ const win = values.slice(-this.size); win.sort((a,b)=>a-b); const idx=Math.floor(0.95*(win.length-1)); return win[idx]; }
}
class ThresholdContext {
  constructor(strategy){ this.strategy=strategy }
  compute(values){ return this.strategy.compute(values) }
}

// usage
const t = new ThresholdContext(new PercentileThreshold(95));
const threshold = t.compute(window);
```

